
const console = { log: (s) => print(s), error: (s) => print(s) };
const clearTimeout = () => {};
const clearInterval = () => {};
const setInterval = () => 1;
const setTimeout = () => 1;
const confirm = () => true;
let lastSpokenUtterance = null;
const window = {
  addEventListener: () => {},
  speechSynthesis: {
    cancel: () => {},
    speak: (u) => { lastSpokenUtterance = u.text; }
  },
  innerWidth: 1200,
  innerHeight: 800,
  scrollX: 0,
  scrollY: 0
};
function SpeechSynthesisUtterance(text) {
  this.text = text;
  this.lang = '';
  this.rate = 1;
}
const elements = {};
const document = {
  getElementById: (id) => {
    if (!elements[id]) {
      elements[id] = {
        id: id,
        value: (id === 'simBaseTimezone' ? 'cairo' : (id === 'simCairoTime' ? '14:00' : (id === 'simEndTime' ? '15:30' : ''))),
        textContent: '',
        innerHTML: '',
        style: { display: 'none' },
        classList: {
          _cls: new Set(),
          add: function(c) { this._cls.add(c); },
          remove: function(c) { this._cls.delete(c); },
          contains: function(c) { return this._cls.has(c); },
          toggle: function(c, v) { if (v) this._cls.add(c); else this._cls.delete(c); }
        },
        focus: () => {},
        querySelectorAll: () => []
      };
    }
    return elements[id];
  },
  querySelectorAll: (sel) => {
    return [];
  },
  addEventListener: () => {},
  body: {
    classList: {
      _cls: new Set(),
      add: function(c) { this._cls.add(c); },
      remove: function(c) { this._cls.delete(c); },
      contains: function(c) { return this._cls.has(c); },
      toggle: function(c) {
        if (this._cls.has(c)) { this._cls.delete(c); return false; }
        else { this._cls.add(c); return true; }
      }
    }
  }
};
const localStorage = {
  _store: {},
  getItem: function(k) { return this._store[k] || null; },
  setItem: function(k, v) { this._store[k] = v; },
  removeItem: function(k) { delete this._store[k]; }
};


