function assertEq(a, b, msg) {
  if (a !== b) {
    throw new Error('FAIL: ' + msg + ' -> expected: ' + b + ', actual: ' + a);
  }
}

function assertTrue(cond, msg) {
  if (!cond) {
    throw new Error('FAIL: ' + msg);
  }
}

